1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"math"
9		"os"
10		"path/filepath"
11		"sort"
12		"strconv"
13		"strings"
14		"time"
15	)
16	
17	// 资产状态、工单状态与履历类型。
18	const (
19		statusAvailable = "可用"
20		statusRepairing = "维修中"
21		ticketOpen      = "未关闭"
22		ticketClosed    = "已关闭"
23		ticketCancelled = "已取消"
24	
25		eventReport = "报修"
26		eventClose  = "关闭"
27		eventCancel = "取消"
28		eventAssign = "派工"
29	
30		eventPlanCreate = "保养建立"
31		eventPlanDone   = "保养完成"
32	
33		eventPartWithdraw = "领用"
34		eventPartReturn   = "退回"
35	
36		eventAttach       = "附件登记"
37		eventAttachRevoke = "附件撤销"
38	
39		storeVersion = 1
40		dataFileName = "caretrack.json"
41	)
42	
43	var (
44		errNotFound = errors.New("not found")
45		errConflict = errors.New("conflict")
46	)
47	
48	// Asset 为登记的设备资产，ID 即企业资产编号。
49	type Asset struct {
50		ID       string `json:"id"`
51		Name     string `json:"name"`
52		Location string `json:"location"`
53		Status   string `json:"status"`
54	}
55	
56	// Ticket 为维修工单。Assignee 为当前（或终结前最后）负责人，空表示未派工；
57	// AssignedAt/AssignNote 为最近一次派工的变更时间与说明。
58	type Ticket struct {
59		ID           string `json:"id"`
60		AssetID      string `json:"asset_id"`
61		Description  string `json:"description"`
62		RequestID    string `json:"request_id"`
63		Status       string `json:"status"`
64		Result       string `json:"result,omitempty"`
65		CreatedAt    string `json:"created_at"`
66		ClosedAt     string `json:"closed_at,omitempty"`
67		CancelReason string `json:"cancel_reason,omitempty"`
68		CancelledAt  string `json:"cancelled_at,omitempty"`
69		Assignee     string `json:"assignee,omitempty"`
70		AssignedAt   string `json:"assigned_at,omitempty"`
71		AssignNote   string `json:"assign_note,omitempty"`
72	}
73	
74	// Event 为履历条目（报修/派工/关闭/取消/保养建立/保养完成/领用/退回/附件登记/附件撤销），Seq 决定操作发生顺序。
75	// From/To 仅派工履历使用：原负责人（首次派工为空，展示为“未派工”）与新负责人。
76	// Due/Done/Interval 仅保养履历使用：建立履历含首次到期日（Due）与间隔天数
77	// （Interval），完成履历含周期到期日（Due）与实际完成日（Done）。
78	// PartID/Quantity/WithdrawalID 仅备件履历使用：领用与退回履历都携带备件编号、
79	// 数量与所属领用编号；Content 分别为领用说明与退回理由。
80	// AttachmentID/Path 仅附件履历使用：登记与撤销履历都携带附件编号与保存的绝对
81	// 路径；Content 分别为附件说明与撤销理由。
82	type Event struct {
83		Seq          int       `json:"-"`
84		AssetID      string    `json:"-"`
85		TicketID     string    `json:"-"`
86		Kind         string    `json:"-"`
87		Content      string    `json:"-"`
88		From         string    `json:"-"`
89		To           string    `json:"-"`
90		Due          string    `json:"-"`
91		Done         string    `json:"-"`
92		Interval     int       `json:"-"`
93		PartID       string    `json:"-"`
94		Quantity     int       `json:"-"`
95		WithdrawalID string    `json:"-"`
96		AttachmentID string    `json:"-"`
97		Path         string    `json:"-"`
98		Time         time.Time `json:"-"`
99	}
100	
101	// eventJSON 与 Event 对应，时间以 RFC3339 文本持久化。
102	type eventJSON struct {
103		Seq          int    `json:"seq"`
104		AssetID      string `json:"asset_id"`
105		TicketID     string `json:"ticket_id,omitempty"`
106		Kind         string `json:"kind"`
107		Content      string `json:"content"`
108		From         string `json:"from,omitempty"`
109		To           string `json:"to,omitempty"`
110		Due          string `json:"due,omitempty"`
111		Done         string `json:"done,omitempty"`
112		Interval     int    `json:"interval,omitempty"`
113		PartID       string `json:"part_id,omitempty"`
114		Quantity     int    `json:"quantity,omitempty"`
115		WithdrawalID string `json:"withdrawal_id,omitempty"`
116		AttachmentID string `json:"attachment_id,omitempty"`
117		Path         string `json:"path,omitempty"`
118		Time         string `json:"time"`
119	}
120	
121	func (e Event) toJSON() eventJSON {
122		return eventJSON{
123			Seq: e.Seq, AssetID: e.AssetID, TicketID: e.TicketID,
124			Kind: e.Kind, Content: e.Content, From: e.From, To: e.To,
125			Due: e.Due, Done: e.Done, Interval: e.Interval,
126			PartID: e.PartID, Quantity: e.Quantity, WithdrawalID: e.WithdrawalID,
127			AttachmentID: e.AttachmentID, Path: e.Path,
128			// RFC3339Nano 保留小数秒精度；整秒时输出与 RFC3339 完全一致，
129			// 因此既有整秒台账的字节表示不变，而旧库中带小数秒的履历时间
130			// 在重新保存（含导入合并后的提交）时也不会被截断。
131			Time: e.Time.Format(time.RFC3339Nano),
132		}
133	}
134	
135	func (e eventJSON) toEvent() (Event, error) {
136		t, err := time.Parse(time.RFC3339, e.Time)
137		if err != nil {
138			return Event{}, fmt.Errorf("履历时间格式无效 %q: %w", e.Time, err)
139		}
140		return Event{
141			Seq: e.Seq, AssetID: e.AssetID, TicketID: e.TicketID,
142			Kind: e.Kind, Content: e.Content, From: e.From, To: e.To,
143			Due: e.Due, Done: e.Done, Interval: e.Interval,
144			PartID: e.PartID, Quantity: e.Quantity, WithdrawalID: e.WithdrawalID,
145			AttachmentID: e.AttachmentID, Path: e.Path,
146			Time: t,
147		}, nil
148	}
149	
150	// PartWithdrawal 为一笔备件领用记录，ID 即领用编号（同目录唯一、不复用）。
151	// 数量表示工单用量；Returned 为累计退回数量，净量 = Quantity - Returned。
152	// 工单关闭或取消后记录与净量保留，不清零。
153	type PartWithdrawal struct {
154		ID       string `json:"id"`
155		TicketID string `json:"ticket_id"`
156		AssetID  string `json:"asset_id"`
157		PartID   string `json:"part_id"`
158		Quantity int    `json:"quantity"`
159		Note     string `json:"note"`
160		Returned int    `json:"returned"`
161	}
162	
163	// requestBinding 记录请求标识与具体报修的绑定，用于去重与冲突拒绝；
164	// 它既不是资产编号也不是工单编号。
165	type requestBinding struct {
166		RequestID   string `json:"request_id"`
167		AssetID     string `json:"asset_id"`
168		Description string `json:"description"`
169		TicketID    string `json:"ticket_id"`
170	}
171	
172	// Attachment 为工单本地资料附件的索引记录，ID 即附件编号（同目录唯一、不复用）。
173	// 只保存引用：Path 为登记时解析得到的绝对路径，工具不复制、不修改、不删除
174	// 资料文件本身。撤销后保留记录、路径、说明（Note）与撤销理由（RevokeReason），
175	// 已撤销编号不能恢复；工单终结不自动撤销附件。
176	type Attachment struct {
177		ID           string `json:"id"`
178		TicketID     string `json:"ticket_id"`
179		AssetID      string `json:"asset_id"`
180		Path         string `json:"path"`
181		Note         string `json:"note"`
182		Revoked      bool   `json:"revoked"`
183		RevokeReason string `json:"revoke_reason,omitempty"`
184	}
185	
186	// storeData 是一次成功写操作共同生效的完整业务数据。
187	type storeData struct {
188		Version       int               `json:"version"`
189		Assets        []*Asset          `json:"assets"`
190		Tickets       []*Ticket         `json:"tickets"`
191		Events        []Event           `json:"-"`
192		EventsJSON    []eventJSON       `json:"events"`
193		Requests      []requestBinding  `json:"requests"`
194		Plans         []*Plan           `json:"plans"`
195		Parts         []*PartWithdrawal `json:"parts"`
196		Attachments   []*Attachment     `json:"attachments"`
197		NextTicketSeq int               `json:"next_ticket_seq"`
198		NextPartSeq   int               `json:"next_part_seq"`
199		NextAttachSeq int               `json:"next_attach_seq"`
200	}
201	
202	type store struct {
203		dir  string
204		data *storeData
205		now  func() time.Time
206	}
207	
208	func newStoreData() *storeData {
209		return &storeData{
210			Version:       storeVersion,
211			Assets:        []*Asset{},
212			Tickets:       []*Ticket{},
213			Events:        []Event{},
214			EventsJSON:    []eventJSON{},
215			Requests:      []requestBinding{},
216			Plans:         []*Plan{},
217			Parts:         []*PartWithdrawal{},
218			Attachments:   []*Attachment{},
219			NextTicketSeq: 1,
220			NextPartSeq:   1,
221			NextAttachSeq: 1,
222		}
223	}
224	
225	// openStore 打开数据目录：目录/文件不存在时视为空库（首次保存时初始化）；
226	// 已有文件为空或无法解析时报告错误并保留原文件，绝不当空库覆盖。
227	func openStore(dir string) (*store, error) {
228		return loadStore(dir, true)
229	}
230	
231	// openSourceStore 以只读用途打开导入源数据目录：与 openStore 做同样的整库
232	// 一致性检查，但源台账必须已存在——不存在时报错，绝不能当空库初始化。
233	func openSourceStore(dir string) (*store, error) {
234		return loadStore(dir, false)
235	}
236	
237	func loadStore(dir string, allowMissing bool) (*store, error) {
238		path := filepath.Join(dir, dataFileName)
239		raw, err := os.ReadFile(path)
240		if err != nil {
241			if errors.Is(err, os.ErrNotExist) {
242				if allowMissing {
243					return &store{dir: dir, data: newStoreData(), now: time.Now}, nil
244				}
245				return nil, fmt.Errorf("源数据文件 %s 不存在：源台账必须已存在，不能当空库处理", path)
246			}
247			return nil, fmt.Errorf("读取数据文件失败: %w", err)
248		}
249		if len(bytes.TrimSpace(raw)) == 0 {
250			return nil, fmt.Errorf("数据文件 %s 已损坏：文件为空（原文件已保留，未做任何修改）", path)
251		}
252		var d storeData
253		if err := json.Unmarshal(raw, &d); err != nil {
254			return nil, fmt.Errorf("数据文件 %s 已损坏：%w（原文件已保留，未做任何修改）", path, err)
255		}
256		if d.EventsJSON != nil {
257			d.Events = make([]Event, len(d.EventsJSON))
258			for i, ej := range d.EventsJSON {
259				ev, err := ej.toEvent()
260				if err != nil {
261					return nil, fmt.Errorf("数据文件 %s 已损坏：%w（原文件已保留，未做任何修改）", path, err)
262				}
263				d.Events[i] = ev
264			}
265		}
266		// 无保养字段的有效旧库直接使用：缺省视为没有任何保养计划。
267		if d.Plans == nil {
268			d.Plans = []*Plan{}
269		}
270		// 无备件字段的有效旧库直接使用：缺省视为没有任何备件领用记录，
271		// 领用编号计数器从 1 开始。
272		if d.Parts == nil {
273			d.Parts = []*PartWithdrawal{}
274		}
275		if d.NextPartSeq == 0 && len(d.Parts) == 0 {
276			d.NextPartSeq = 1
277		}
278		// 无附件字段的有效旧库直接使用：缺省视为没有任何附件索引记录，
279		// 附件编号计数器从 1 开始。
280		if d.Attachments == nil {
281			d.Attachments = []*Attachment{}
282		}
283		if d.NextAttachSeq == 0 && len(d.Attachments) == 0 {
284			d.NextAttachSeq = 1
285		}
286		if err := validateData(&d); err != nil {
287			return nil, fmt.Errorf("数据文件 %s 内容相互矛盾：%w（原文件已保留，未做任何修改）", path, err)
288		}
289		return &store{dir: dir, data: &d, now: time.Now}, nil
290	}
291	
292	// parseTicketSeq 解析 T 加补零正整数序号形式的工单编号，返回序号。
293	// 编号必须与 fmt.Sprintf("T%04d", n)（n ≥ 1）完全一致，否则视为非法。
294	func parseTicketSeq(id string) (int, bool) {
295		if !strings.HasPrefix(id, "T") {
296			return 0, false
297		}
298		n, err := strconv.Atoi(id[1:])
299		if err != nil || n < 1 {
300			return 0, false
301		}
302		if fmt.Sprintf("T%04d", n) != id {
303			return 0, false
304		}
305		return n, true
306	}
307	
308	// parsePartSeq 解析 P 加补零正整数序号形式的领用编号，返回序号。
309	// 编号必须与 fmt.Sprintf("P%04d", n)（n ≥ 1）完全一致，否则视为非法。
310	func parsePartSeq(id string) (int, bool) {
311		if !strings.HasPrefix(id, "P") {
312			return 0, false
313		}
314		n, err := strconv.Atoi(id[1:])
315		if err != nil || n < 1 {
316			return 0, false
317		}
318		if fmt.Sprintf("P%04d", n) != id {
319			return 0, false
320		}
321		return n, true
322	}
323	
324	// parseAttachSeq 解析 A 加补零正整数序号形式的附件编号，返回序号。
325	// 编号必须与 fmt.Sprintf("A%04d", n)（n ≥ 1）完全一致，否则视为非法。
326	func parseAttachSeq(id string) (int, bool) {
327		if !strings.HasPrefix(id, "A") {
328			return 0, false
329		}
330		n, err := strconv.Atoi(id[1:])
331		if err != nil || n < 1 {
332			return 0, false
333		}
334		if fmt.Sprintf("A%04d", n) != id {
335			return 0, false
336		}
337		return n, true
338	}
339	
340	// validateData 校验整份业务数据的内部一致性。任何矛盾都会返回指明问题类别
341	// （计数器/请求绑定/状态/履历）的错误；调用方必须拒绝查询与写入并保留原文件。
342	// 不做任何修复：不补字段、不重编号、不删除记录。
343	func validateData(d *storeData) error {
344		if d.Version != storeVersion {
345			return fmt.Errorf("不支持的数据版本 %d", d.Version)
346		}
347		if d.Assets == nil || d.Tickets == nil || d.Requests == nil || d.EventsJSON == nil || d.Events == nil || d.Plans == nil || d.Parts == nil || d.Attachments == nil {
348			return errors.New("缺少必要的数据段")
349		}
350		assets := map[string]*Asset{}
351		for _, a := range d.Assets {
352			if a == nil || a.ID == "" || a.Name == "" || a.Location == "" {
353				return errors.New("数据矛盾：存在字段不完整的资产记录")
354			}
355			if a.Status != statusAvailable && a.Status != statusRepairing {
356				return fmt.Errorf("状态矛盾：资产 %s 状态无效 %q", a.ID, a.Status)
357			}
358			if assets[a.ID] != nil {
359				return fmt.Errorf("数据矛盾：资产编号 %s 重复", a.ID)
360			}
361			assets[a.ID] = a
362		}
363		tickets := map[string]*Ticket{}
364		maxTicketSeq := 0
365		for _, t := range d.Tickets {
366			if t == nil || t.ID == "" || t.AssetID == "" || t.RequestID == "" || t.Description == "" || t.CreatedAt == "" {
367				return errors.New("数据矛盾：存在字段不完整的工单记录（工单描述不能为空）")
368			}
369			n, ok := parseTicketSeq(t.ID)
370			if !ok {
371				return fmt.Errorf("计数器矛盾：工单编号 %q 不是 T 加补零正整数序号的形式", t.ID)
372			}
373			if n > maxTicketSeq {
374				maxTicketSeq = n
375			}
376			if t.Status != ticketOpen && t.Status != ticketClosed && t.Status != ticketCancelled {
377				return fmt.Errorf("状态矛盾：工单 %s 状态无效 %q", t.ID, t.Status)
378			}
379			if assets[t.AssetID] == nil {
380				return fmt.Errorf("数据矛盾：工单 %s 引用了不存在的资产 %s", t.ID, t.AssetID)
381			}
382			if t.Status == ticketClosed && (t.Result == "" || t.ClosedAt == "") {
383				return fmt.Errorf("状态矛盾：已关闭工单 %s 缺少维修结果或关闭时间", t.ID)
384			}
385			if t.Status == ticketCancelled && (t.CancelReason == "" || t.CancelledAt == "") {
386				return fmt.Errorf("状态矛盾：已取消工单 %s 缺少取消理由或取消时间", t.ID)
387			}
388			if t.Status != ticketClosed && (t.Result != "" || t.ClosedAt != "") {
389				return fmt.Errorf("状态矛盾：非已关闭工单 %s 不应带有维修结果或关闭时间", t.ID)
390			}
391			if t.Status != ticketCancelled && (t.CancelReason != "" || t.CancelledAt != "") {
392				return fmt.Errorf("状态矛盾：非已取消工单 %s 不应带有取消理由或取消时间", t.ID)
393			}
394			if t.Assignee == "" {
395				if t.AssignedAt != "" || t.AssignNote != "" {
396					return fmt.Errorf("状态矛盾：未派工工单 %s 不应带有派工时间或派工说明", t.ID)
397				}
398			} else if t.AssignedAt == "" || t.AssignNote == "" {
399				return fmt.Errorf("状态矛盾：已派工工单 %s 缺少派工时间或派工说明", t.ID)
400			}
401			if tickets[t.ID] != nil {
402				return fmt.Errorf("数据矛盾：工单编号 %s 重复", t.ID)
403			}
404			tickets[t.ID] = t
405		}
406		// 下一工单序号必须为正并大于全部已用序号（允许有间隔）。
407		if d.NextTicketSeq < 1 || d.NextTicketSeq <= maxTicketSeq {
408			return fmt.Errorf("计数器矛盾：下一工单序号 %d 必须为正并大于全部已用序号（当前最大 %d）",
409				d.NextTicketSeq, maxTicketSeq)
410		}
411		// 备件领用记录：编号唯一且为 P 加补零正整数序号，归属存在的工单且资产归属
412		// 与工单一致，数量为正，累计退回在 [0, 原数量] 内；与履历的接续在下方按
413		// 履历序号重放时核对。
414		parts := map[string]*PartWithdrawal{}
415		maxPartSeq := 0
416		for _, p := range d.Parts {
417			if p == nil || p.ID == "" || p.TicketID == "" || p.AssetID == "" || p.PartID == "" || p.Note == "" {
418				return errors.New("数据矛盾：存在字段不完整的备件领用记录")
419			}
420			n, ok := parsePartSeq(p.ID)
421			if !ok {
422				return fmt.Errorf("计数器矛盾：领用编号 %q 不是 P 加补零正整数序号的形式", p.ID)
423			}
424			if n > maxPartSeq {
425				maxPartSeq = n
426			}
427			if p.Quantity < 1 {
428				return fmt.Errorf("数据矛盾：领用记录 %s 的数量 %d 不是正整数", p.ID, p.Quantity)
429			}
430			if p.Returned < 0 || p.Returned > p.Quantity {
431				return fmt.Errorf("备件数量矛盾：领用记录 %s 的累计退回 %d 超出原数量 %d", p.ID, p.Returned, p.Quantity)
432			}
433			t := tickets[p.TicketID]
434			if t == nil {
435				return fmt.Errorf("数据矛盾：领用记录 %s 引用了不存在的工单 %s", p.ID, p.TicketID)
436			}
437			if t.AssetID != p.AssetID {
438				return fmt.Errorf("数据矛盾：领用记录 %s 的资产 %s 与工单 %s 归属的资产 %s 不一致",
439					p.ID, p.AssetID, t.ID, t.AssetID)
440			}
441			if parts[p.ID] != nil {
442				return fmt.Errorf("数据矛盾：领用编号 %s 重复", p.ID)
443			}
444			parts[p.ID] = p
445		}
446		// 下一领用序号必须为正并大于全部已用序号（允许有间隔）。
447		if d.NextPartSeq < 1 || d.NextPartSeq <= maxPartSeq {
448			return fmt.Errorf("计数器矛盾：下一领用序号 %d 必须为正并大于全部已用序号（当前最大 %d）",
449				d.NextPartSeq, maxPartSeq)
450		}
451		// 附件索引记录：编号唯一且为 A 加补零正整数序号，归属存在的工单且资产归属
452		// 与工单一致，路径为绝对路径，说明非空；撤销状态与理由相互呼应。文件当前
453		// 是否可用不参与整库一致性校验；与履历的接续在下方按履历序号重放时核对。
454		attachments := map[string]*Attachment{}
455		maxAttachSeq := 0
456		for _, a := range d.Attachments {
457			if a == nil || a.ID == "" || a.TicketID == "" || a.AssetID == "" || a.Path == "" || a.Note == "" {
458				return errors.New("数据矛盾：存在字段不完整的附件记录")
459			}
460			n, ok := parseAttachSeq(a.ID)
461			if !ok {
462				return fmt.Errorf("计数器矛盾：附件编号 %q 不是 A 加补零正整数序号的形式", a.ID)
463			}
464			if n > maxAttachSeq {
465				maxAttachSeq = n
466			}
467			if !filepath.IsAbs(a.Path) {
468				return fmt.Errorf("数据矛盾：附件记录 %s 的路径 %q 不是绝对路径", a.ID, a.Path)
469			}
470			t := tickets[a.TicketID]
471			if t == nil {
472				return fmt.Errorf("数据矛盾：附件记录 %s 引用了不存在的工单 %s", a.ID, a.TicketID)
473			}
474			if t.AssetID != a.AssetID {
475				return fmt.Errorf("数据矛盾：附件记录 %s 的资产 %s 与工单 %s 归属的资产 %s 不一致",
476					a.ID, a.AssetID, t.ID, t.AssetID)
477			}
478			if a.Revoked && a.RevokeReason == "" {
479				return fmt.Errorf("状态矛盾：已撤销附件 %s 缺少撤销理由", a.ID)
480			}
481			if !a.Revoked && a.RevokeReason != "" {
482				return fmt.Errorf("状态矛盾：有效附件 %s 不应带有撤销理由", a.ID)
483			}
484			if attachments[a.ID] != nil {
485				return fmt.Errorf("数据矛盾：附件编号 %s 重复", a.ID)
486			}
487			attachments[a.ID] = a
488		}
489		// 下一附件序号必须为正并大于全部已用序号（允许有间隔）。
490		if d.NextAttachSeq < 1 || d.NextAttachSeq <= maxAttachSeq {
491			return fmt.Errorf("计数器矛盾：下一附件序号 %d 必须为正并大于全部已用序号（当前最大 %d）",
492				d.NextAttachSeq, maxAttachSeq)
493		}
494		// 请求绑定：每张工单恰有一条绑定，且请求标识、资产、描述、工单编号完全一致。
495		boundReq := map[string]bool{}
496		boundTicket := map[string]bool{}
497		for _, r := range d.Requests {
498			if r.RequestID == "" || r.AssetID == "" || r.Description == "" || r.TicketID == "" {
499				return errors.New("请求绑定矛盾：存在字段不完整的请求绑定记录")
500			}
501			if boundReq[r.RequestID] {
502				return fmt.Errorf("请求绑定矛盾：请求标识 %s 被绑定多次", r.RequestID)
503			}
504			boundReq[r.RequestID] = true
505			t := tickets[r.TicketID]
506			if t == nil {
507				return fmt.Errorf("请求绑定矛盾：请求标识 %s 绑定的工单 %s 不存在", r.RequestID, r.TicketID)
508			}
509			if t.RequestID != r.RequestID {
510				return fmt.Errorf("请求绑定矛盾：工单 %s 的请求标识为 %s，绑定记录却来自请求 %s",
511					r.TicketID, t.RequestID, r.RequestID)
512			}
513			if r.AssetID != t.AssetID || r.Description != t.Description {
514				return fmt.Errorf("请求绑定矛盾：请求标识 %s 绑定的资产编号或故障描述与工单 %s 不一致",
515					r.RequestID, t.ID)
516			}
517			boundTicket[r.TicketID] = true
518		}
519		for _, t := range d.Tickets {
520			if !boundTicket[t.ID] {
521				return fmt.Errorf("请求绑定矛盾：工单 %s 缺少对应的报修请求绑定", t.ID)
522			}
523		}
524		// 状态：每项资产最多一张未关闭工单，有则“维修中”，无则“可用”。
525		openCount := map[string]int{}
526		for _, t := range d.Tickets {
527			if t.Status == ticketOpen {
528				openCount[t.AssetID]++
529			}
530		}
531		for _, a := range d.Assets {
532			c := openCount[a.ID]
533			if c > 1 {
534				return fmt.Errorf("状态矛盾：资产 %s 有 %d 张未关闭工单，最多允许一张", a.ID, c)
535			}
536			want := statusAvailable
537			if c == 1 {
538				want = statusRepairing
539			}
540			if a.Status != want {
541				return fmt.Errorf("状态矛盾：资产 %s 有 %d 张未关闭工单，状态应为 %s，实际为 %s",
542					a.ID, c, want, a.Status)
543			}
544		}
545		// 履历：序号全库唯一且为正整数；归属、内容与工单一致。
546		seenSeq := map[int]bool{}
547		reportSeq := map[string]int{}
548		closeSeq := map[string]int{}
549		cancelSeq := map[string]int{}
550		reportCount := map[string]int{}
551		closeCount := map[string]int{}
552		cancelCount := map[string]int{}
553		for i := range d.Events {
554			e := &d.Events[i]
555			if e.Seq < 1 {
556				return fmt.Errorf("履历矛盾：履历序号 %d 不是正整数", e.Seq)
557			}
558			if seenSeq[e.Seq] {
559				return fmt.Errorf("履历矛盾：履历序号 %d 重复", e.Seq)
560			}
561			seenSeq[e.Seq] = true
562			if e.AssetID == "" || e.Kind == "" || e.Content == "" {
563				return errors.New("履历矛盾：存在字段不完整的履历记录")
564			}
565			if e.Kind == eventPlanCreate || e.Kind == eventPlanDone {
566				// 保养履历：不属于任何工单，不携带派工字段；日期与间隔在此核对，
567				// 建立及完成链的接续在下方按序号重放时核对。
568				if e.TicketID != "" || e.From != "" || e.To != "" {
569					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录不应带有工单编号或派工人员字段", e.Seq, e.Kind)
570				}
571				due, err := parseDate(e.Due)
572				if err != nil {
573					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录到期日无效", e.Seq, e.Kind)
574				}
575				if e.Kind == eventPlanCreate {
576					if e.Done != "" {
577						return fmt.Errorf("履历矛盾：履历序号 %d 的建立记录不应带有完成日", e.Seq)
578					}
579					if e.Interval < 1 {
580						return fmt.Errorf("履历矛盾：履历序号 %d 的建立记录间隔天数须为正整数", e.Seq)
581					}
582				} else {
583					if e.Interval != 0 {
584						return fmt.Errorf("履历矛盾：履历序号 %d 的完成记录不应带有间隔天数", e.Seq)
585					}
586					done, err := parseDate(e.Done)
587					if err != nil {
588						return fmt.Errorf("履历矛盾：履历序号 %d 的完成记录完成日无效", e.Seq)
589					}
590					if done < due {
591						return fmt.Errorf("履历矛盾：履历序号 %d 的完成日早于周期到期日", e.Seq)
592					}
593				}
594				continue
595			}
596			if e.TicketID == "" {
597				return errors.New("履历矛盾：存在字段不完整的履历记录")
598			}
599			if e.Due != "" || e.Done != "" || e.Interval != 0 {
600				return fmt.Errorf("履历矛盾：履历序号 %d 的维修履历不应带有保养字段", e.Seq)
601			}
602			if e.Kind != eventAssign && (e.From != "" || e.To != "") {
603				return fmt.Errorf("履历矛盾：履历序号 %d 的 %s 记录不应带有派工人员字段", e.Seq, e.Kind)
604			}
605			if e.Kind == eventAssign {
606				if e.To == "" {
607					return fmt.Errorf("履历矛盾：履历序号 %d 的派工记录缺少新负责人", e.Seq)
608				}
609				if e.From == e.To {
610					return fmt.Errorf("履历矛盾：履历序号 %d 的派工记录新负责人与原负责人相同", e.Seq)
611				}
612			}
613			// 附件字段仅附件履历携带；附件履历不携带备件字段。
614			if e.Kind != eventAttach && e.Kind != eventAttachRevoke && (e.AttachmentID != "" || e.Path != "") {
615				return fmt.Errorf("履历矛盾：履历序号 %d 的 %s 记录不应带有附件编号或路径", e.Seq, e.Kind)
616			}
617			if (e.Kind == eventAttach || e.Kind == eventAttachRevoke) &&
618				(e.PartID != "" || e.Quantity != 0 || e.WithdrawalID != "") {
619				return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录不应带有备件字段", e.Seq, e.Kind)
620			}
621			t := tickets[e.TicketID]
622			if t == nil || assets[e.AssetID] == nil {
623				return fmt.Errorf("履历矛盾：履历序号 %d 引用了不存在的资产或工单", e.Seq)
624			}
625			if e.AssetID != t.AssetID {
626				return fmt.Errorf("履历矛盾：履历序号 %d 的资产 %s 与工单 %s 归属的资产 %s 不一致",
627					e.Seq, e.AssetID, t.ID, t.AssetID)
628			}
629			switch e.Kind {
630			case eventReport:
631				if e.Content != t.Description {
632					return fmt.Errorf("履历矛盾：工单 %s 的报修履历内容与故障描述不一致", t.ID)
633				}
634				reportCount[t.ID]++
635				reportSeq[t.ID] = e.Seq
636			case eventClose:
637				if e.Content != t.Result {
638					return fmt.Errorf("履历矛盾：工单 %s 的关闭履历内容与维修结果不一致", t.ID)
639				}
640				closeCount[t.ID]++
641				closeSeq[t.ID] = e.Seq
642			case eventCancel:
643				if e.Content != t.CancelReason {
644					return fmt.Errorf("履历矛盾：工单 %s 的取消履历内容与取消理由不一致", t.ID)
645				}
646				cancelCount[t.ID]++
647				cancelSeq[t.ID] = e.Seq
648			case eventAssign:
649				// 内容即派工说明（非空已检查）；派工链的接续与工单负责人一致性
650				// 在下方按序号重放时核对。
651			case eventPartWithdraw, eventPartReturn:
652				// 内容即领用说明或退回理由（非空已检查）；备件字段在此核对，
653				// 与领用记录的接续及累计退回在下方按序号重放时核对。
654				if e.PartID == "" || e.WithdrawalID == "" {
655					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录缺少备件编号或领用编号", e.Seq, e.Kind)
656				}
657				if e.Quantity < 1 {
658					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录数量 %d 不是正整数", e.Seq, e.Kind, e.Quantity)
659				}
660				if _, ok := parsePartSeq(e.WithdrawalID); !ok {
661					return fmt.Errorf("履历矛盾：履历序号 %d 的领用编号 %q 不是 P 加补零正整数序号的形式",
662						e.Seq, e.WithdrawalID)
663				}
664			case eventAttach, eventAttachRevoke:
665				// 内容即附件说明或撤销理由（非空已检查）；附件字段在此核对，
666				// 与附件记录的接续及登记、撤销顺序在下方按序号重放时核对。
667				if e.AttachmentID == "" || e.Path == "" {
668					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录缺少附件编号或路径", e.Seq, e.Kind)
669				}
670				if _, ok := parseAttachSeq(e.AttachmentID); !ok {
671					return fmt.Errorf("履历矛盾：履历序号 %d 的附件编号 %q 不是 A 加补零正整数序号的形式",
672						e.Seq, e.AttachmentID)
673				}
674				if !filepath.IsAbs(e.Path) {
675					return fmt.Errorf("履历矛盾：履历序号 %d 的附件路径 %q 不是绝对路径", e.Seq, e.Path)
676				}
677			default:
678				return fmt.Errorf("履历矛盾：履历序号 %d 的事件类型无效 %q", e.Seq, e.Kind)
679			}
680		}
681		for _, t := range d.Tickets {
682			if reportCount[t.ID] != 1 {
683				return fmt.Errorf("履历矛盾：工单 %s 应有恰一条报修履历，实际 %d 条", t.ID, reportCount[t.ID])
684			}
685			if t.Status == ticketClosed {
686				if closeCount[t.ID] != 1 {
687					return fmt.Errorf("履历矛盾：已关闭工单 %s 应有恰一条关闭履历，实际 %d 条", t.ID, closeCount[t.ID])
688				}
689				if closeSeq[t.ID] <= reportSeq[t.ID] {
690					return fmt.Errorf("履历矛盾：工单 %s 的关闭履历（序号 %d）不在报修履历（序号 %d）之后",
691						t.ID, closeSeq[t.ID], reportSeq[t.ID])
692				}
693			} else if closeCount[t.ID] != 0 {
694				return fmt.Errorf("履历矛盾：非已关闭工单 %s 不得有关闭履历", t.ID)
695			}
696			if t.Status == ticketCancelled {
697				if cancelCount[t.ID] != 1 {
698					return fmt.Errorf("履历矛盾：已取消工单 %s 应有恰一条取消履历，实际 %d 条", t.ID, cancelCount[t.ID])
699				}
700				if cancelSeq[t.ID] <= reportSeq[t.ID] {
701					return fmt.Errorf("履历矛盾：工单 %s 的取消履历（序号 %d）不在报修履历（序号 %d）之后",
702						t.ID, cancelSeq[t.ID], reportSeq[t.ID])
703				}
704			} else if cancelCount[t.ID] != 0 {
705				return fmt.Errorf("履历矛盾：非已取消工单 %s 不得有取消履历", t.ID)
706			}
707		}
708		// 按履历序号推进，重放得到的工单与资产状态须与保存的状态相符；
709		// 同一资产的上一张工单必须先关闭或取消才可产生下一张报修。
710		sorted := make([]Event, len(d.Events))
711		copy(sorted, d.Events)
712		sort.SliceStable(sorted, func(i, j int) bool { return sorted[i].Seq < sorted[j].Seq })
713		derivedTicket := map[string]string{}
714		derivedOpen := map[string]string{}
715		derivedAssignee := map[string]string{}
716		derivedNote := map[string]string{}
717		withdrawSeq := map[string]int{}
718		derivedReturned := map[string]int{}
719		attachRegSeq := map[string]int{}
720		attachRevokeSeq := map[string]int{}
721		for _, e := range sorted {
722			switch e.Kind {
723			case eventReport:
724				if derivedTicket[e.TicketID] != "" {
725					return fmt.Errorf("履历矛盾：工单 %s 被重复报修", e.TicketID)
726				}
727				if prev := derivedOpen[e.AssetID]; prev != "" {
728					return fmt.Errorf("履历矛盾：资产 %s 的上一张工单 %s 尚未结束就产生了工单 %s 的报修",
729						e.AssetID, prev, e.TicketID)
730				}
731				derivedTicket[e.TicketID] = ticketOpen
732				derivedOpen[e.AssetID] = e.TicketID
733			case eventAssign:
734				if derivedTicket[e.TicketID] != ticketOpen {
735					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现派工履历", e.TicketID)
736				}
737				if e.From != derivedAssignee[e.TicketID] {
738					return fmt.Errorf("履历矛盾：工单 %s 的派工履历（序号 %d）原负责人 %q 与上次记录不接续",
739						e.TicketID, e.Seq, e.From)
740				}
741				derivedAssignee[e.TicketID] = e.To
742				derivedNote[e.TicketID] = e.Content
743			case eventClose:
744				if derivedTicket[e.TicketID] != ticketOpen {
745					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现关闭履历", e.TicketID)
746				}
747				derivedTicket[e.TicketID] = ticketClosed
748				delete(derivedOpen, e.AssetID)
749			case eventCancel:
750				if derivedTicket[e.TicketID] != ticketOpen {
751					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现取消履历", e.TicketID)
752				}
753				derivedTicket[e.TicketID] = ticketCancelled
754				delete(derivedOpen, e.AssetID)
755			case eventPartWithdraw:
756				// 领用须在报修之后、终结之前；履历与领用记录的业务字段必须一致。
757				if derivedTicket[e.TicketID] != ticketOpen {
758					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现领用履历（序号 %d）",
759						e.TicketID, e.Seq)
760				}
761				p := parts[e.WithdrawalID]
762				if p == nil {
763					return fmt.Errorf("履历矛盾：领用履历（序号 %d）引用了不存在的领用记录 %s",
764						e.Seq, e.WithdrawalID)
765				}
766				if withdrawSeq[p.ID] != 0 {
767					return fmt.Errorf("履历矛盾：领用记录 %s 有多条领用履历", p.ID)
768				}
769				if p.TicketID != e.TicketID || p.AssetID != e.AssetID || p.PartID != e.PartID ||
770					p.Quantity != e.Quantity || p.Note != e.Content {
771					return fmt.Errorf("履历矛盾：领用履历（序号 %d）与领用记录 %s 的工单、资产、备件、数量或说明不一致",
772						e.Seq, p.ID)
773				}
774				withdrawSeq[p.ID] = e.Seq
775			case eventPartReturn:
776				// 退回须在报修之后、终结之前，且指向先前已领用的记录；
777				// 累计退回不得超过该笔原数量。
778				if derivedTicket[e.TicketID] != ticketOpen {
779					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现退回履历（序号 %d）",
780						e.TicketID, e.Seq)
781				}
782				p := parts[e.WithdrawalID]
783				if p == nil {
784					return fmt.Errorf("履历矛盾：退回履历（序号 %d）引用了不存在的领用记录 %s",
785						e.Seq, e.WithdrawalID)
786				}
787				if withdrawSeq[p.ID] == 0 {
788					return fmt.Errorf("履历矛盾：退回履历（序号 %d）出现在领用记录 %s 的领用履历之前",
789						e.Seq, p.ID)
790				}
791				if p.TicketID != e.TicketID || p.AssetID != e.AssetID || p.PartID != e.PartID {
792					return fmt.Errorf("履历矛盾：退回履历（序号 %d）与领用记录 %s 的工单、资产或备件不一致",
793						e.Seq, p.ID)
794				}
795				// 逐步核对累计退回不超过原数量：先做不会溢出的减法比较再累加。
796				// 直接相加可能整数溢出回绕，即使回绕后的累计恰好等于保存值，
797				// 实际超额的履历也必须拒绝。
798				if e.Quantity > p.Quantity-derivedReturned[p.ID] {
799					return fmt.Errorf("备件数量矛盾：领用记录 %s 的累计退回在履历序号 %d 处超过原数量 %d",
800						p.ID, e.Seq, p.Quantity)
801				}
802				derivedReturned[p.ID] += e.Quantity
803			case eventAttach:
804				// 登记须在报修之后；未关闭、已关闭或已取消工单均可补充资料。
805				// 履历与附件记录的业务字段必须一致。
806				if derivedTicket[e.TicketID] == "" {
807					return fmt.Errorf("履历矛盾：工单 %s 在报修之前出现附件登记履历（序号 %d）",
808						e.TicketID, e.Seq)
809				}
810				a := attachments[e.AttachmentID]
811				if a == nil {
812					return fmt.Errorf("履历矛盾：附件登记履历（序号 %d）引用了不存在的附件记录 %s",
813						e.Seq, e.AttachmentID)
814				}
815				if attachRegSeq[a.ID] != 0 {
816					return fmt.Errorf("履历矛盾：附件记录 %s 有多条登记履历", a.ID)
817				}
818				if a.TicketID != e.TicketID || a.AssetID != e.AssetID || a.Path != e.Path || a.Note != e.Content {
819					return fmt.Errorf("履历矛盾：附件登记履历（序号 %d）与附件记录 %s 的工单、资产、路径或说明不一致",
820						e.Seq, a.ID)
821				}
822				attachRegSeq[a.ID] = e.Seq
823			case eventAttachRevoke:
824				// 撤销须在登记之后，且每个附件至多撤销一次；
825				// 履历与附件记录的业务字段必须一致。
826				if derivedTicket[e.TicketID] == "" {
827					return fmt.Errorf("履历矛盾：工单 %s 在报修之前出现附件撤销履历（序号 %d）",
828						e.TicketID, e.Seq)
829				}
830				a := attachments[e.AttachmentID]
831				if a == nil {
832					return fmt.Errorf("履历矛盾：附件撤销履历（序号 %d）引用了不存在的附件记录 %s",
833						e.Seq, e.AttachmentID)
834				}
835				if attachRegSeq[a.ID] == 0 {
836					return fmt.Errorf("履历矛盾：附件撤销履历（序号 %d）出现在附件记录 %s 的登记履历之前",
837						e.Seq, a.ID)
838				}
839				if attachRevokeSeq[a.ID] != 0 {
840					return fmt.Errorf("履历矛盾：附件记录 %s 有多条撤销履历", a.ID)
841				}
842				if a.TicketID != e.TicketID || a.AssetID != e.AssetID || a.Path != e.Path || a.RevokeReason != e.Content {
843					return fmt.Errorf("履历矛盾：附件撤销履历（序号 %d）与附件记录 %s 的工单、资产、路径或撤销理由不一致",
844						e.Seq, a.ID)
845				}
846				attachRevokeSeq[a.ID] = e.Seq
847			}
848		}
849		for _, t := range d.Tickets {
850			if derivedTicket[t.ID] != t.Status {
851				return fmt.Errorf("状态矛盾：按履历推进得到工单 %s 状态为 %s，与保存的 %s 不符",
852					t.ID, derivedTicket[t.ID], t.Status)
853			}
854			// 由履历推出的最后负责人须与工单记录一致；无派工履历则必须未派工。
855			if derivedAssignee[t.ID] != t.Assignee {
856				return fmt.Errorf("状态矛盾：按履历推出工单 %s 最后负责人为 %q，与保存的 %q 不符",
857					t.ID, derivedAssignee[t.ID], t.Assignee)
858			}
859			if t.Assignee != "" && derivedNote[t.ID] != t.AssignNote {
860				return fmt.Errorf("状态矛盾：工单 %s 保存的派工说明与最后一次派工履历不一致", t.ID)
861			}
862		}
863		// 每笔领用记录恰有一条领用履历；按履历重放得到的累计退回须与保存值一致。
864		for _, p := range d.Parts {
865			if withdrawSeq[p.ID] == 0 {
866				return fmt.Errorf("履历矛盾：领用记录 %s 缺少对应的领用履历", p.ID)
867			}
868			if derivedReturned[p.ID] != p.Returned {
869				return fmt.Errorf("备件数量矛盾：按履历推出领用记录 %s 的累计退回为 %d，与保存的 %d 不符",
870					p.ID, derivedReturned[p.ID], p.Returned)
871			}
872		}
873		// 每条附件记录恰有一条登记履历、至多一条撤销履历；记录的撤销状态须与
874		// 是否存在撤销履历一致。
875		for _, a := range d.Attachments {
876			if attachRegSeq[a.ID] == 0 {
877				return fmt.Errorf("履历矛盾：附件记录 %s 缺少对应的登记履历", a.ID)
878			}
879			if revoked := attachRevokeSeq[a.ID] != 0; revoked != a.Revoked {
880				return fmt.Errorf("状态矛盾：附件记录 %s 保存的撤销状态与履历不符", a.ID)
881			}
882		}
883		for _, a := range d.Assets {
884			want := statusAvailable
885			if derivedOpen[a.ID] != "" {
886				want = statusRepairing
887			}
888			if a.Status != want {
889				return fmt.Errorf("状态矛盾：按履历推进得到资产 %s 状态为 %s，与保存的 %s 不符",
890					a.ID, want, a.Status)
891			}
892		}
893		// 保养计划：归属存在的资产、每项资产最多一个、日期有效、间隔为正整数。
894		plans := map[string]*Plan{}
895		for _, p := range d.Plans {
896			if p == nil || p.AssetID == "" || p.Content == "" {
897				return errors.New("数据矛盾：存在字段不完整的保养计划")
898			}
899			if assets[p.AssetID] == nil {
900				return fmt.Errorf("数据矛盾：保养计划引用了不存在的资产 %s", p.AssetID)
901			}
902			if plans[p.AssetID] != nil {
903				return fmt.Errorf("数据矛盾：资产 %s 有多个保养计划，最多允许一个", p.AssetID)
904			}
905			if _, err := parseDate(p.FirstDue); err != nil {
906				return fmt.Errorf("数据矛盾：资产 %s 保养计划的首次到期日无效", p.AssetID)
907			}
908			if p.IntervalDays < 1 {
909				return fmt.Errorf("数据矛盾：资产 %s 保养计划的间隔天数须为正整数", p.AssetID)
910			}
911			if _, err := parseDate(p.NextDue); err != nil {
912				return fmt.Errorf("数据矛盾：资产 %s 保养计划的下一到期日无效", p.AssetID)
913			}
914			plans[p.AssetID] = p
915		}
916		// 保养履历链：每个计划恰有一条建立履历（内容、首次到期日、间隔与计划一致），
917		// 完成履历按序号接续（周期到期日须等于当前下一到期日，完成日不早于它），
918		// 由履历推出的下一到期日须与计划保存的一致。没有计划的资产不得有保养履历。
919		maintCreate := map[string]int{}
920		derivedDue := map[string]string{}
921		for _, e := range sorted {
922			if e.Kind != eventPlanCreate && e.Kind != eventPlanDone {
923				continue
924			}
925			p := plans[e.AssetID]
926			if p == nil {
927				return fmt.Errorf("履历矛盾：资产 %s 没有保养计划，却存在保养履历（序号 %d）", e.AssetID, e.Seq)
928			}
929			if e.Kind == eventPlanCreate {
930				if maintCreate[e.AssetID] != 0 {
931					return fmt.Errorf("履历矛盾：资产 %s 有多条保养建立履历", e.AssetID)
932				}
933				maintCreate[e.AssetID] = e.Seq
934				if e.Content != p.Content || e.Due != p.FirstDue || e.Interval != p.IntervalDays {
935					return fmt.Errorf("履历矛盾：资产 %s 的保养建立履历与计划内容、首次到期日或间隔不一致", e.AssetID)
936				}
937				derivedDue[e.AssetID] = e.Due
938				continue
939			}
940			if maintCreate[e.AssetID] == 0 {
941				return fmt.Errorf("履历矛盾：资产 %s 的保养完成履历（序号 %d）出现在建立履历之前", e.AssetID, e.Seq)
942			}
943			if e.Due != derivedDue[e.AssetID] {
944				return fmt.Errorf("履历矛盾：资产 %s 的保养完成履历（序号 %d）周期到期日 %s 与当前下一到期日 %s 不接续",
945					e.AssetID, e.Seq, e.Due, derivedDue[e.AssetID])
946			}
947			first, _ := parseDate(p.FirstDue)
948			done, _ := parseDate(e.Done)
949			next, ok := nextDueAfter(first, int64(p.IntervalDays), done)
950			if !ok {
951				return fmt.Errorf("履历矛盾：资产 %s 的保养完成履历（序号 %d）无法推出日期范围内的下一到期日",
952					e.AssetID, e.Seq)
953			}
954			derivedDue[e.AssetID] = formatDate(next)
955		}
956		for _, p := range d.Plans {
957			if maintCreate[p.AssetID] == 0 {
958				return fmt.Errorf("履历矛盾：资产 %s 的保养计划应有恰一条建立履历，实际没有", p.AssetID)
959			}
960			if derivedDue[p.AssetID] != p.NextDue {
961				return fmt.Errorf("履历矛盾：按履历推出资产 %s 的下一到期日为 %s，与保存的 %s 不符",
962					p.AssetID, derivedDue[p.AssetID], p.NextDue)
963			}
964		}
965		return nil
966	}
