968	// save 将全部业务数据一次性原子写入：先写同目录临时文件，fsync 后 rename
969	// 覆盖正式文件。写入前先校验待提交数据的一致性；校验或读写失败时原文件
970	// 保持不变，不留下部分业务变化。
971	func (s *store) save() error {
972		s.data.EventsJSON = make([]eventJSON, len(s.data.Events))
973		for i, e := range s.data.Events {
974			s.data.EventsJSON[i] = e.toJSON()
975		}
976		if err := validateData(s.data); err != nil {
977			return fmt.Errorf("待保存数据未通过一致性检查：%w（未写入任何数据）", err)
978		}
979		var buf bytes.Buffer
980		enc := json.NewEncoder(&buf)
981		enc.SetIndent("", "  ")
982		if err := enc.Encode(s.data); err != nil {
983			return fmt.Errorf("编码数据失败: %w", err)
984		}
985		if err := os.MkdirAll(s.dir, 0o755); err != nil {
986			return fmt.Errorf("创建数据目录失败: %w", err)
987		}
988		path := filepath.Join(s.dir, dataFileName)
989		tmp, err := os.CreateTemp(s.dir, ".caretrack-*.tmp")
990		if err != nil {
991			return fmt.Errorf("创建临时数据文件失败: %w", err)
992		}
993		tmpName := tmp.Name()
994		abort := func(err error) error {
995			_ = tmp.Close()
996			_ = os.Remove(tmpName)
997			return err
998		}
999		if _, err := tmp.Write(buf.Bytes()); err != nil {
1000			abort(nil)
1001			return fmt.Errorf("写入数据失败: %w", err)
1002		}
1003		if err := tmp.Sync(); err != nil {
1004			abort(nil)
1005			return fmt.Errorf("写入数据失败: %w", err)
1006		}
1007		if err := tmp.Close(); err != nil {
1008			_ = os.Remove(tmpName)
1009			return fmt.Errorf("写入数据失败: %w", err)
1010		}
1011		if err := os.Rename(tmpName, path); err != nil {
1012			_ = os.Remove(tmpName)
1013			return fmt.Errorf("保存数据失败: %w", err)
1014		}
1015		return nil
1016	}
