1065	// nextEventSeq 返回下一条履历应使用的全库唯一正整数序号；计数器耗尽时报错。
1066	func (s *store) nextEventSeq() (int, error) {
1067		maxSeq := 0
1068		for _, e := range s.data.Events {
1069			if e.Seq > maxSeq {
1070				maxSeq = e.Seq
1071			}
1072		}
1073		if maxSeq == math.MaxInt {
1074			return 0, fmt.Errorf("%w: 履历序号计数器已耗尽，无法追加履历", errConflict)
1075		}
1076		return maxSeq + 1, nil
1077	}
