1103	// report 创建报修工单。返回 (工单, 是否为去重重放, 错误)。
1104	// 所有失败路径都不修改任何业务数据，也不会绑定新的请求标识。
1105	func (s *store) report(assetID, description, requestID string) (*Ticket, bool, error) {
1106		// 已有绑定：相同资产+描述 => 返回原工单（无论其是否已关闭、是否已有新工单）；
1107		// 资产或描述不同 => 拒绝。
1108		if r := s.findRequest(requestID); r != nil {
1109			if r.AssetID != assetID || r.Description != description {
1110				return nil, false, fmt.Errorf(
1111					"%w: 请求标识 %q 已用于资产 %q 的另一笔报修，不能搭配不同的资产编号或故障描述",
1112					errConflict, requestID, r.AssetID)
1113			}
1114			t := s.findTicket(r.TicketID)
1115			if t == nil {
1116				return nil, false, fmt.Errorf("数据内部错误：请求标识 %q 绑定的工单不存在", requestID)
1117			}
1118			return t, true, nil
1119		}
1120	
1121		asset := s.findAsset(assetID)
1122		if asset == nil {
1123			return nil, false, fmt.Errorf("%w: 未知资产编号 %q", errNotFound, assetID)
1124		}
1125		if t := s.openTicketOf(assetID); t != nil {
1126			return nil, false, fmt.Errorf("%w: 资产 %s 已有未关闭工单 %s", errConflict, assetID, t.ID)
1127		}
1128		// 先确认编号与履历计数器都能推进，再修改任何业务数据：
1129		// 编号耗尽时拒绝新报修，不消耗编号，也不绑定请求标识。
1130		seq := s.data.NextTicketSeq
1131		if seq < 1 || seq == math.MaxInt {
1132			return nil, false, fmt.Errorf("%w: 工单编号计数器已耗尽，无法分配新工单编号", errConflict)
1133		}
1134		eventSeq, err := s.nextEventSeq()
1135		if err != nil {
1136			return nil, false, err
1137		}
1138		t := &Ticket{
1139			ID:          fmt.Sprintf("T%04d", seq),
1140			AssetID:     assetID,
1141			Description: description,
1142			RequestID:   requestID,
1143			Status:      ticketOpen,
1144			CreatedAt:   s.now().Format(time.RFC3339),
1145		}
1146		s.data.NextTicketSeq = seq + 1
1147		s.data.Tickets = append(s.data.Tickets, t)
1148		s.data.Requests = append(s.data.Requests, requestBinding{
1149			RequestID:   requestID,
1150			AssetID:     assetID,
1151			Description: description,
1152			TicketID:    t.ID,
1153		})
1154		asset.Status = statusRepairing
1155		s.appendEvent(eventSeq, assetID, t.ID, eventReport, description, "", "")
1156		return t, false, nil
1157	}
1158	
1159	// closeTicket 关闭未关闭工单并把资产恢复为可用。
1160	// 失败路径不修改任何业务数据。
1161	func (s *store) closeTicket(ticketID, result string) (*Ticket, *Asset, error) {
1162		t := s.findTicket(ticketID)
1163		if t == nil {
1164			return nil, nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
1165		}
1166		if t.Status == ticketCancelled {
1167			return nil, nil, fmt.Errorf("%w: 工单 %s 已取消，不能关闭", errConflict, ticketID)
1168		}
1169		if t.Status != ticketOpen {
1170			return nil, nil, fmt.Errorf("%w: 工单 %s 已关闭，不能重复关闭", errConflict, ticketID)
1171		}
1172		asset := s.findAsset(t.AssetID)
1173		if asset == nil {
1174			return nil, nil, fmt.Errorf("数据内部错误：工单 %s 引用的资产不存在", ticketID)
1175		}
1176		eventSeq, err := s.nextEventSeq()
1177		if err != nil {
1178			return nil, nil, err
1179		}
1180		t.Status = ticketClosed
1181		t.Result = result
1182		t.ClosedAt = s.now().Format(time.RFC3339)
1183		asset.Status = statusAvailable
1184		s.appendEvent(eventSeq, asset.ID, t.ID, eventClose, result, "", "")
1185		return t, asset, nil
1186	}
1187	
1188	// cancelTicket 取消未关闭工单并把资产恢复为可用。取消是终态，但不代表维修完成：
1189	// 不填写维修结果，不删除工单、履历或请求绑定，工单编号不回退也不复用。
1190	// 失败路径不修改任何业务数据。
1191	func (s *store) cancelTicket(ticketID, reason string) (*Ticket, *Asset, error) {
1192		t := s.findTicket(ticketID)
1193		if t == nil {
1194			return nil, nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
1195		}
1196		if t.Status == ticketCancelled {
1197			return nil, nil, fmt.Errorf("%w: 工单 %s 已取消，不能再次取消", errConflict, ticketID)
1198		}
1199		if t.Status == ticketClosed {
1200			return nil, nil, fmt.Errorf("%w: 工单 %s 已关闭，不能取消", errConflict, ticketID)
1201		}
1202		asset := s.findAsset(t.AssetID)
1203		if asset == nil {
1204			return nil, nil, fmt.Errorf("数据内部错误：工单 %s 引用的资产不存在", ticketID)
1205		}
1206		eventSeq, err := s.nextEventSeq()
1207		if err != nil {
1208			return nil, nil, err
1209		}
1210		t.Status = ticketCancelled
1211		t.CancelReason = reason
1212		t.CancelledAt = s.now().Format(time.RFC3339)
1213		asset.Status = statusAvailable
1214		s.appendEvent(eventSeq, asset.ID, t.ID, eventCancel, reason, "", "")
1215		return t, asset, nil
1216	}
1217	
1218	// assignTicket 为未关闭工单派工或转派：没有负责人时首次派工，已有负责人时
1219	// 转派给不同人员。人员标识只是本地文本记录，不对应任何人员账户。
1220	// 成功后保存负责人、变更时间与说明，并追加一条含原负责人（首次派工为空，
1221	// 展示为“未派工”）、新负责人及说明的派工履历。派工不创建工单、不消耗工单
1222	// 编号，也不改变资产状态或报修请求绑定。失败路径不修改任何业务数据。
1223	func (s *store) assignTicket(ticketID, assignee, note string) (*Ticket, error) {
1224		t := s.findTicket(ticketID)
1225		if t == nil {
1226			return nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
1227		}
1228		if t.Status == ticketClosed {
1229			return nil, fmt.Errorf("%w: 工单 %s 已关闭，不能派工", errConflict, ticketID)
1230		}
1231		if t.Status == ticketCancelled {
1232			return nil, fmt.Errorf("%w: 工单 %s 已取消，不能派工", errConflict, ticketID)
1233		}
1234		if assignee == "" {
1235			return nil, fmt.Errorf("%w: 维修人员标识不能为空", errConflict)
1236		}
1237		if note == "" {
1238			return nil, fmt.Errorf("%w: 派工说明不能为空", errConflict)
1239		}
1240		if t.Assignee == assignee {
1241			return nil, fmt.Errorf("%w: 工单 %s 当前负责人已是 %s，不能重复派给同一人",
1242				errConflict, ticketID, assignee)
1243		}
1244		eventSeq, err := s.nextEventSeq()
1245		if err != nil {
1246			return nil, err
1247		}
1248		s.appendEvent(eventSeq, t.AssetID, t.ID, eventAssign, note, t.Assignee, assignee)
1249		t.Assignee = assignee
1250		t.AssignedAt = s.now().Format(time.RFC3339)
1251		t.AssignNote = note
1252		return t, nil
1253	}
1254

