1	package main
2	
3	import (
4		"errors"
5		"fmt"
6		"io"
7		"math"
8		"os"
9		"path/filepath"
10		"sort"
11		"strings"
12	)
13	
14	// 资产批量导入：把源数据目录中所选资产连同其全部工单、报修请求绑定、
15	// 报修/派工/关闭/取消履历、备件领用记录、附件索引（含登记/撤销履历）与
16	// 保养计划（含保养建立/完成履历）复制到目标数据目录。
17	//
18	// 关键规则：
19	//   - 导入是复制：源台账始终只读，不删除、不修改任何源记录；同一台账不能导入自身。
20	//   - 工单编号按源工单序号升序，从目标的下一工单序号重新分配，并同步替换履历与
21	//     请求绑定中的工单引用；目标原有记录不改编号、不改变业务含义。
22	//   - 备件领用编号按源领用履历的全库序号整体排序（编号大小不代表领用先后），
23	//     从目标的下一领用序号重新分配并输出映射；领用记录的工单引用与退回履历中的
24	//     领用引用同步替换，数量、累计退回与净量保持。导入的未关闭工单可继续退回。
25	//   - 附件编号按源登记履历的全库序号整体排序，从目标的下一附件序号重新分配并
26	//     输出映射；附件记录的工单引用与登记、撤销履历中的附件引用同步替换，路径、
27	//     撤销状态、说明与理由保持。只复制索引，不复制资料文件；文件当前不可用不使
28	//     导入失败。
29	//   - 履历按源履历序号排列，在目标已有最大履历序号之后依次分配新序号，保留原操作
30	//     顺序（不按时间重排）；履历时间保留原瞬间与小数秒精度。导入本身不追加报修
31	//     或其他业务事件。
32	//   - 保养计划随资产原样复制（内容、首次到期日、间隔与下一到期日不变），保养履历
33	//     随资产履历一并复制，完成链自然接续；目标已有计划不受影响。
34	//   - 资产编号在目标已存在，或所选工单的任一请求标识已在目标绑定时，整批拒绝：
35	//     不覆盖、不合并、不改请求标识。
36	//   - 操作前检查源、目标整库一致性，提交前由 save 再检查合并后的数据；整批变化
37	//     一次原子写入目标。任何失败都不改动两边原文件、不留下部分导入、不消耗目标编号。
38	
39	// stringListFlag 收集可重复的 --asset-id 参数。
40	type stringListFlag []string
41	
42	func (f *stringListFlag) String() string { return strings.Join(*f, ",") }
43	
44	func (f *stringListFlag) Set(v string) error {
45		*f = append(*f, v)
46		return nil
47	}
48	
49	// ticketRemap 记录一张工单的原编号与新编号。
50	type ticketRemap struct {
51		OldID string
52		NewID string
53	}
54	
55	// partRemap 记录一笔备件领用的原领用编号与新领用编号。
56	type partRemap struct {
57		OldID string
58		NewID string
59	}
60	
61	// attachRemap 记录一条附件索引的原附件编号与新附件编号。
62	type attachRemap struct {
63		OldID string
64		NewID string
65	}
66	
67	// importOutcome 为一次成功导入的结果摘要，用于输出。
68	type importOutcome struct {
69		assetIDs    []string
70		tickets     []ticketRemap
71		parts       []partRemap
72		attachments []attachRemap
73		plans       int
74	}
75	
76	func cmdImport(args []string, w io.Writer) error {
77		var opts cmdOptions
78		var sourceDir string
79		var assetIDs stringListFlag
80		fs := newFlagSet("import", &opts)
81		fs.StringVar(&sourceDir, "source-dir", "", "源数据目录（必填，只读，不会被修改）")
82		fs.Var(&assetIDs, "asset-id", "要导入的资产编号（必填，可重复；重复编号按一项处理）")
83		if err := parseFlags(fs, args); err != nil {
84			return err
85		}
86		if err := requireFlag(fs, sourceDir, "source-dir"); err != nil {
87			return err
88		}
89		if len(assetIDs) == 0 {
90			return &usageError{msg: "命令 import 缺少必填参数 --asset-id（至少一项资产编号）"}
91		}
92		for _, id := range assetIDs {
93			if id == "" {
94				return &usageError{msg: "命令 import 的 --asset-id 不能为空"}
95			}
96		}
97	
98		outcome, err := importAssets(opts.dataDir, sourceDir, []string(assetIDs))
99		if err != nil {
100			return err
101		}
102		fmt.Fprintf(w, "已导入 %d 项资产（%s）。\n", len(outcome.assetIDs), strings.Join(outcome.assetIDs, ", "))
103		if outcome.plans > 0 {
104			fmt.Fprintf(w, "同时导入 %d 项保养计划及其保养履历。\n", outcome.plans)
105		}
106		if len(outcome.tickets) == 0 {
107			fmt.Fprintln(w, "所选资产没有工单，未分配新工单编号。")
108		} else {
109			fmt.Fprintln(w, "工单编号映射（原编号 -> 新编号）:")
110			for _, m := range outcome.tickets {
111				fmt.Fprintf(w, "%s -> %s\n", m.OldID, m.NewID)
112			}
113		}
114		if len(outcome.parts) > 0 {
115			fmt.Fprintln(w, "领用编号映射（原编号 -> 新编号）:")
116			for _, m := range outcome.parts {
117				fmt.Fprintf(w, "%s -> %s\n", m.OldID, m.NewID)
118			}
119		}
120		if len(outcome.attachments) > 0 {
121			fmt.Fprintln(w, "附件编号映射（原编号 -> 新编号）:")
122			for _, m := range outcome.attachments {
123				fmt.Fprintf(w, "%s -> %s\n", m.OldID, m.NewID)
124			}
125		}
126		return nil
127	}
128	
129	// importAssets 把 sourceDir 中编号为 assetIDs 的资产导入 targetDir。
130	// 源目录只读；目标目录无台账时在成功导入时创建。任何一步失败都整批失败，
131	// 两边原文件字节保持不变。
132	func importAssets(targetDir, sourceDir string, assetIDs []string) (*importOutcome, error) {
133		srcAbs, err := filepath.Abs(sourceDir)
134		if err != nil {
135			return nil, fmt.Errorf("无法解析源数据目录: %w", err)
136		}
137		dstAbs, err := filepath.Abs(targetDir)
138		if err != nil {
139			return nil, fmt.Errorf("无法解析目标数据目录: %w", err)
140		}
141		if srcAbs == dstAbs {
142			return nil, errors.New("源数据目录与目标数据目录相同：同一台账不能导入自身")
143		}
144		// 路径不同也可能指向同一台账文件（符号链接等），按文件再判一次。
145		srcPath := filepath.Join(srcAbs, dataFileName)
146		dstPath := filepath.Join(dstAbs, dataFileName)
147		if fi1, err1 := os.Stat(srcPath); err1 == nil {
148			if fi2, err2 := os.Stat(dstPath); err2 == nil && os.SameFile(fi1, fi2) {
149				return nil, errors.New("源与目标指向同一台账文件：同一台账不能导入自身")
150			}
151		}
152	
153		// 源台账必须已存在并通过整库一致性检查；源始终只读，绝不写入。
154		src, err := openSourceStore(srcAbs)
155		if err != nil {
156			return nil, err
157		}
158		// 目标：无台账时视为空库（成功导入时创建）；已有台账同样先做整库一致性检查。
159		dst, err := openStore(dstAbs)
160		if err != nil {
161			return nil, err
162		}
163		outcome, err := dst.mergeImport(src, assetIDs)
164		if err != nil {
165			return nil, err
166		}
167		// save 先校验合并后的整库一致性，再一次性原子写入；失败时目标原文件不变。
168		if err := dst.save(); err != nil {
169			return nil, err
170		}
171		return outcome, nil
172	}
173	
174	// mergeImport 在内存中把源台账的所选资产合并进目标数据：先做全部冲突与容量
175	// 检查，再一次性应用，任何失败都不会留下部分变更。调用方负责随后的原子保存。
176	func (s *store) mergeImport(src *store, assetIDs []string) (*importOutcome, error) {
177		// 重复编号按一项处理，保持首次出现的顺序。
178		selected := map[string]bool{}
179		ids := make([]string, 0, len(assetIDs))
180		for _, id := range assetIDs {
181			if !selected[id] {
182				selected[id] = true
183				ids = append(ids, id)
184			}
185		}
186		// 所选资产必须存在于源，且编号在目标中不存在。
187		assets := make([]*Asset, 0, len(ids))
188		for _, id := range ids {
189			a := src.findAsset(id)
190			if a == nil {
191				return nil, fmt.Errorf("%w: 源台账中不存在资产编号 %q", errNotFound, id)
192			}
193			if s.findAsset(id) != nil {
194				return nil, fmt.Errorf("%w: 资产编号 %q 在目标台账中已存在，整批拒绝导入", errConflict, id)
195			}
196			assets = append(assets, a)
197		}
198		// 所选资产的全部工单，按源工单序号升序重新分配编号。
199		tickets := make([]*Ticket, 0)
200		for _, t := range src.data.Tickets {
201			if selected[t.AssetID] {
202				tickets = append(tickets, t)
203			}
204		}
205		sort.SliceStable(tickets, func(i, j int) bool {
206			ni, _ := parseTicketSeq(tickets[i].ID)
207			nj, _ := parseTicketSeq(tickets[j].ID)
208			return ni < nj
209		})
210		// 工单编号容量：与 report 同一约束，可分配的最大序号为 math.MaxInt-1。
211		if len(tickets) > math.MaxInt-s.data.NextTicketSeq {
212			return nil, fmt.Errorf(
213				"%w: 目标工单编号容量不足：下一序号 %d 无法容纳 %d 张导入工单，整批拒绝导入",
214				errConflict, s.data.NextTicketSeq, len(tickets))
215		}
216		// 所选工单的任一请求标识已在目标绑定时整批拒绝，不改请求标识。
217		srcReqByTicket := map[string]*requestBinding{}
218		for i := range src.data.Requests {
219			r := &src.data.Requests[i]
220			srcReqByTicket[r.TicketID] = r
221		}
222		for _, t := range tickets {
223			r := srcReqByTicket[t.ID]
224			if r == nil {
225				return nil, fmt.Errorf("数据内部错误：源工单 %s 缺少报修请求绑定", t.ID)
226			}
227			if s.findRequest(r.RequestID) != nil {
228				return nil, fmt.Errorf(
229					"%w: 所选工单的请求标识 %q 已在目标台账绑定，整批拒绝导入", errConflict, r.RequestID)
230			}
231		}
232		// 所选资产的全部履历，按源履历序号升序，在目标最大序号之后依次分配。
233		events := make([]Event, 0)
234		for _, e := range src.data.Events {
235			if selected[e.AssetID] {
236				events = append(events, e)
237			}
238		}
239		sort.SliceStable(events, func(i, j int) bool { return events[i].Seq < events[j].Seq })
240		maxSeq := 0
241		for _, e := range s.data.Events {
242			if e.Seq > maxSeq {
243				maxSeq = e.Seq
244			}
245		}
246		// 履历序号容量：与 nextEventSeq 同一约束，可分配的最大序号为 math.MaxInt。
247		if len(events) > math.MaxInt-maxSeq {
248			return nil, fmt.Errorf(
249				"%w: 目标履历序号容量不足：当前最大序号 %d 无法容纳 %d 条导入履历，整批拒绝导入",
250				errConflict, maxSeq, len(events))
251		}
252		// 所选工单的全部备件领用记录，按源领用履历的全库序号整体排序（领用编号
253		// 只定位记录，编号大小不代表领用先后），再按此顺序重新分配领用编号。
254		srcTicketIDs := map[string]bool{}
255		for _, t := range tickets {
256			srcTicketIDs[t.ID] = true
257		}
258		srcWithdrawSeq := map[string]int{}
259		for _, e := range src.data.Events {
260			if e.Kind == eventPartWithdraw {
261				srcWithdrawSeq[e.WithdrawalID] = e.Seq
262			}
263		}
264		parts := make([]*PartWithdrawal, 0)
265		for _, p := range src.data.Parts {
266			if srcTicketIDs[p.TicketID] {
267				parts = append(parts, p)
268			}
269		}
270		sort.SliceStable(parts, func(i, j int) bool {
271			return srcWithdrawSeq[parts[i].ID] < srcWithdrawSeq[parts[j].ID]
272		})
273		// 领用编号容量：与 withdrawPart 同一约束，可分配的最大序号为 math.MaxInt-1。
274		if len(parts) > math.MaxInt-s.data.NextPartSeq {
275			return nil, fmt.Errorf(
276				"%w: 目标领用编号容量不足：下一序号 %d 无法容纳 %d 笔导入领用，整批拒绝导入",
277				errConflict, s.data.NextPartSeq, len(parts))
278		}
279		// 所选工单的全部附件索引（有效与已撤销都复制），按源登记履历的全库序号
280		// 整体排序（附件编号只定位记录，编号大小不代表登记先后），再按此顺序重新
281		// 分配附件编号。只复制索引记录与履历，不复制资料文件；文件当前不可用不使
282		// 导入失败。
283		srcAttachRegSeq := map[string]int{}
284		for _, e := range src.data.Events {
285			if e.Kind == eventAttach {
286				srcAttachRegSeq[e.AttachmentID] = e.Seq
287			}
288		}
289		attachments := make([]*Attachment, 0)
290		for _, a := range src.data.Attachments {
291			if srcTicketIDs[a.TicketID] {
292				attachments = append(attachments, a)
293			}
294		}
295		sort.SliceStable(attachments, func(i, j int) bool {
296			return srcAttachRegSeq[attachments[i].ID] < srcAttachRegSeq[attachments[j].ID]
297		})
298		// 附件编号容量：与 attach 同一约束，可分配的最大序号为 math.MaxInt-1。
299		if len(attachments) > math.MaxInt-s.data.NextAttachSeq {
300			return nil, fmt.Errorf(
301				"%w: 目标附件编号容量不足：下一序号 %d 无法容纳 %d 条导入附件索引，整批拒绝导入",
302				errConflict, s.data.NextAttachSeq, len(attachments))
303		}
304	
305		// 检查全部通过，一次性应用合并。资产编号、名称、位置、状态与工单的描述、
306		// 终态内容、负责人等业务信息原样保留；履历时间保留原瞬间与小数秒精度。
307		for _, a := range assets {
308			na := *a
309			s.data.Assets = append(s.data.Assets, &na)
310		}
311		// 所选资产的保养计划原样复制（内容、首次到期日、间隔与下一到期日不变）；
312		// 保养履历已随上方资产履历筛选一并复制，完成链自然接续。目标已有计划不变。
313		planCount := 0
314		for _, p := range src.data.Plans {
315			if selected[p.AssetID] {
316				np := *p
317				s.data.Plans = append(s.data.Plans, &np)
318				planCount++
319			}
320		}
321		outcome := &importOutcome{assetIDs: ids, plans: planCount}
322		remap := map[string]string{}
323		next := s.data.NextTicketSeq
324		for _, t := range tickets {
325			nt := *t
326			nt.ID = fmt.Sprintf("T%04d", next)
327			remap[t.ID] = nt.ID
328			s.data.Tickets = append(s.data.Tickets, &nt)
329			r := srcReqByTicket[t.ID]
330			s.data.Requests = append(s.data.Requests, requestBinding{
331				RequestID:   r.RequestID,
332				AssetID:     r.AssetID,
333				Description: r.Description,
334				TicketID:    nt.ID,
335			})
336			outcome.tickets = append(outcome.tickets, ticketRemap{OldID: t.ID, NewID: nt.ID})
337			next++
338		}
339		s.data.NextTicketSeq = next
340		// 备件领用记录按源领用顺序重新分配领用编号，工单引用同步替换；
341		// 数量、累计退回与说明等业务信息原样保留。
342		partIDs := map[string]string{}
343		nextPart := s.data.NextPartSeq
344		for _, p := range parts {
345			np := *p
346			np.ID = fmt.Sprintf("P%04d", nextPart)
347			np.TicketID = remap[p.TicketID]
348			partIDs[p.ID] = np.ID
349			s.data.Parts = append(s.data.Parts, &np)
350			outcome.parts = append(outcome.parts, partRemap{OldID: p.ID, NewID: np.ID})
351			nextPart++
352		}
353		s.data.NextPartSeq = nextPart
354		// 附件索引按源登记顺序重新分配附件编号，工单引用同步替换；
355		// 路径、撤销状态、说明与撤销理由等业务信息原样保留。
356		attachIDs := map[string]string{}
357		nextAttach := s.data.NextAttachSeq
358		for _, a := range attachments {
359			na := *a
360			na.ID = fmt.Sprintf("A%04d", nextAttach)
361			na.TicketID = remap[a.TicketID]
362			attachIDs[a.ID] = na.ID
363			s.data.Attachments = append(s.data.Attachments, &na)
364			outcome.attachments = append(outcome.attachments, attachRemap{OldID: a.ID, NewID: na.ID})
365			nextAttach++
366		}
367		s.data.NextAttachSeq = nextAttach
368		seq := maxSeq
369		for _, e := range events {
370			seq++
371			ne := e
372			ne.Seq = seq
373			ne.TicketID = remap[e.TicketID]
374			ne.WithdrawalID = partIDs[e.WithdrawalID]
375			ne.AttachmentID = attachIDs[e.AttachmentID]
376			s.data.Events = append(s.data.Events, ne)
377		}
378		return outcome, nil
379	}
