206			t.Fatal(err)
207		}
208		if _, next, err := s.completePlan("EQ-2", "2024-02-28", "2024-02-28", "完成"); err != nil || next != "2024-02-29" {
209			t.Fatalf("跨闰日: next=%q err=%v", next, err)
210		}
211		// 2100 年不是闰年：2100-02-28 + 1 = 2100-03-01。
