227		}
228		if _, next, err := s.completePlan("EQ-4", "2024-02-27", "2024-03-01", "完成"); err != nil || next != "2024-03-02" {
229			t.Fatalf("延期跨闰日: next=%q err=%v", next, err)
230		}
