565	// 矛盾保养数据（计划归属、唯一性、日期、建立及完成链、推出日期）加载即报错，
566	// 不自动修复，原文件保留。
567	func TestPlanConsistencyRejected(t *testing.T) {
568		// 在 baseLedger 基础上附加合法的保养数据，再分别破坏。
569		basePlan := func(m map[string]any) {
570			m["plans"] = []any{map[string]any{
571				"asset_id": "EQ-1", "content": "更换滤芯",
572				"first_due": "2026-11-01", "interval_days": 90, "next_due": "2026-11-01",
573			}}
574			appendTo(m, "events", map[string]any{
575				"seq": 4, "asset_id": "EQ-1", "kind": "保养建立", "content": "更换滤芯",
576				"due": "2026-11-01", "interval": 90, "time": "2026-10-01T12:00:00Z",
577			})
578		}
579		cases := map[string]func(m map[string]any){
580			"计划引用不存在的资产": func(m map[string]any) {
581				basePlan(m)
582				m["plans"].([]any)[0].(map[string]any)["asset_id"] = "EQ-X"
583			},
584			"同一资产两个计划": func(m map[string]any) {
585				basePlan(m)
586				m["plans"] = append(m["plans"].([]any), map[string]any{
587					"asset_id": "EQ-1", "content": "另一个",
588					"first_due": "2026-11-01", "interval_days": 90, "next_due": "2026-11-01",
589				})
590			},
591			"首次到期日无效": func(m map[string]any) {
592				basePlan(m)
593				m["plans"].([]any)[0].(map[string]any)["first_due"] = "2026-02-29"
594			},
595			"间隔非正整数": func(m map[string]any) {
596				basePlan(m)
597				m["plans"].([]any)[0].(map[string]any)["interval_days"] = 0
598			},
599			"缺少建立履历": func(m map[string]any) {
600				m["plans"] = []any{map[string]any{
601					"asset_id": "EQ-1", "content": "更换滤芯",
602					"first_due": "2026-11-01", "interval_days": 90, "next_due": "2026-11-01",
603				}}
604			},
605			"建立履历与计划不符": func(m map[string]any) {
606				basePlan(m)
607				m["plans"].([]any)[0].(map[string]any)["content"] = "其他内容"
608			},
609			"完成链接续断裂": func(m map[string]any) {
610				basePlan(m)
611				appendTo(m, "events", map[string]any{
612					"seq": 5, "asset_id": "EQ-1", "kind": "保养完成", "content": "已更换",
613					"due": "2026-11-02", "done": "2026-11-02", "time": "2026-10-01T13:00:00Z",
614				})
615				m["plans"].([]any)[0].(map[string]any)["next_due"] = "2027-01-31"
616			},
617			"推出日期与保存不符": func(m map[string]any) {
618				basePlan(m)
619				appendTo(m, "events", map[string]any{
620					"seq": 5, "asset_id": "EQ-1", "kind": "保养完成", "content": "已更换",
621					"due": "2026-11-01", "done": "2026-11-02", "time": "2026-10-01T13:00:00Z",
622				})
623				m["plans"].([]any)[0].(map[string]any)["next_due"] = "2026-11-01"
624			},
625			"无计划却有保养履历": func(m map[string]any) {
626				appendTo(m, "events", map[string]any{
627					"seq": 4, "asset_id": "EQ-1", "kind": "保养建立", "content": "更换滤芯",
628					"due": "2026-11-01", "interval": 90, "time": "2026-10-01T12:00:00Z",
629				})
630			},
631		}
632		for name, mutate := range cases {
633			t.Run(name, func(t *testing.T) {
634				dir := t.TempDir()
635				raw := writeLedger(t, dir, mutate)
636				if _, err := openStore(dir); err == nil {
637					t.Fatal("矛盾数据应报错")
638				} else if !strings.Contains(err.Error(), "矛盾") {
639					t.Fatalf("错误应指出矛盾，得到 %v", err)
640				}
641				// 原文件保留，不自动修复。
642				if got := readFileBytes(t, dir); !bytes.Equal(got, raw) {
643					t.Fatal("原文件不应被修改")
644				}
645			})
646		}
647		// 合法的保养数据可以加载。
648		dir := t.TempDir()
649		writeLedger(t, dir, basePlan)
650		s, err := openStore(dir)
651		if err != nil {
652			t.Fatalf("合法保养数据应能加载: %v", err)
653		}
654		if got := s.findPlan("EQ-1"); got == nil || got.NextDue != "2026-11-01" {
655			t.Fatalf("计划未加载: %+v", got)
656		}
657	}
658	
659	// 参数错误退出码 2，业务失败退出码 1。
660	func TestMaintenanceExitCodes(t *testing.T) {
661		dir := t.TempDir()
662		var out, errOut bytes.Buffer
663		// 缺少必填参数、非法日期、非正间隔 → 2。
664		for _, args := range [][]string{
665			{"plan", "--data-dir", dir, "--asset-id", "EQ-1", "--content", "x", "--first-due", "2026-11-01"},
666			{"plan", "--data-dir", dir, "--asset-id", "EQ-1", "--content", "x", "--first-due", "2026-13-01", "--interval-days", "90"},
667			{"plan", "--data-dir", dir, "--asset-id", "EQ-1", "--content", "x", "--first-due", "2026-11-01", "--interval-days", "-3"},
668			{"maintain", "--data-dir", dir, "--asset-id", "EQ-1", "--due", "bad", "--done", "2026-11-01", "--result", "x"},
669			{"due", "--data-dir", dir, "--date", "2026-1-1"},
670		} {
671			out.Reset()
672			errOut.Reset()
673			if code := run(args, &out, &errOut); code != 2 {
674				t.Fatalf("参数错误应退出 2: %v → %d (%s)", args, code, errOut.String())
675			}
676		}
677		// 未知资产 → 1。
678		out.Reset()
679		errOut.Reset()
680		code := run([]string{"plan", "--data-dir", dir, "--asset-id", "NOPE", "--content", "x",
681			"--first-due", "2026-11-01", "--interval-days", "90"}, &out, &errOut)
682		if code != 1 {
683			t.Fatalf("业务失败应退出 1，得到 %d", code)
684		}
685		// 建立后重复建立 → 1；成功 → 0。
686		out.Reset()
687		errOut.Reset()
688		code = run([]string{"register", "--data-dir", dir, "--asset-id", "EQ-1", "--name", "打印机", "--location", "一楼"}, &out, &errOut)
689		if code != 0 {
690			t.Fatalf("register: %d %s", code, errOut.String())
691		}
692		out.Reset()
693		errOut.Reset()
694		code = run([]string{"plan", "--data-dir", dir, "--asset-id", "EQ-1", "--content", "更换滤芯",
695			"--first-due", "2026-11-01", "--interval-days", "90"}, &out, &errOut)
696		if code != 0 || !strings.Contains(out.String(), "首次到期日: 2026-11-01") {
697			t.Fatalf("plan 应成功并显示首次到期日: %d %s %s", code, out.String(), errOut.String())
698		}
699		out.Reset()
700		errOut.Reset()
701		code = run([]string{"plan", "--data-dir", dir, "--asset-id", "EQ-1", "--content", "覆盖",
702			"--first-due", "2027-01-01", "--interval-days", "30"}, &out, &errOut)
703		if code != 1 {
704			t.Fatalf("重复建立应退出 1，得到 %d", code)
705		}
706		// 完成登记成功输出完成周期与下一到期日。
707		out.Reset()
708		errOut.Reset()
709		code = run([]string{"maintain", "--data-dir", dir, "--asset-id", "EQ-1",
710			"--due", "2026-11-01", "--done", "2026-11-03", "--result", "已更换"}, &out, &errOut)
711		if code != 0 || !strings.Contains(out.String(), "已完成周期 2026-11-01") ||
712			!strings.Contains(out.String(), "下一到期日: 2027-01-30") {
713			t.Fatalf("maintain 输出不对: %d %s %s", code, out.String(), errOut.String())
714		}
715	}
