188	// 撤销后恢复的周期可按原规则重新完成，生成新序号；旧序号的再次撤销仍拒绝，
189	// 不能误撤销新登记。
190	func TestRevokeThenRecompleteSameCycle(t *testing.T) {
191		s := newTestStore(t)
192		if _, err := s.registerAsset("EQ-1", "打印机", "一楼"); err != nil {
193			t.Fatal(err)
194		}
195		if _, err := s.createPlan("EQ-1", "更换滤芯", "2026-01-01", 10); err != nil {
196			t.Fatal(err)
197		}
198		_, _, seq1, err := s.completePlan("EQ-1", "2026-01-01", "2026-01-05", "第一次")
199		if err != nil {
200			t.Fatal(err)
201		}
202		if _, _, err := s.revokeCompletion("EQ-1", seq1, "误登记"); err != nil {
203			t.Fatal(err)
204		}
205		if got := s.findPlan("EQ-1"); got.NextDue != "2026-01-01" {
206			t.Fatalf("撤销后下一到期日 = %q", got.NextDue)
207		}
208		// 同一周期按原 maintain 规则重新完成，生成新序号。
209		_, next, seq2, err := s.completePlan("EQ-1", "2026-01-01", "2026-01-02", "重新登记")
210		if err != nil || next != "2026-01-11" {
211			t.Fatalf("重新完成: next=%q err=%v", next, err)
212		}
213		if seq2 == seq1 {
214			t.Fatal("重新完成应生成新序号")
215		}
216		// 旧序号的再次撤销仍拒绝（已撤销），不会误撤销新登记。
217		if _, _, err := s.revokeCompletion("EQ-1", seq1, "再次"); !errors.Is(err, errConflict) {
218			t.Fatalf("旧序号再次撤销应拒绝，得到 %v", err)
219		}
220		if got := s.findPlan("EQ-1"); got.NextDue != "2026-01-11" {
221			t.Fatalf("旧序号撤销不应影响新登记，下一到期日 = %q", got.NextDue)
222		}
223		// 新登记可用新序号正常撤销。
224		if _, _, err := s.revokeCompletion("EQ-1", seq2, "又登错了"); err != nil {
225			t.Fatalf("新序号撤销: %v", err)
226		}
227		if got := s.findPlan("EQ-1"); got.NextDue != "2026-01-01" {
228			t.Fatalf("撤销新登记后下一到期日 = %q", got.NextDue)
229		}
230		// 重启后保持。
231		s = saveAndReopen(t, s)
232		if got := s.findPlan("EQ-1"); got.NextDue != "2026-01-01" {
233			t.Fatalf("重开后下一到期日 = %q", got.NextDue)
234		}
235	}
